// The scene page owns master backgrounds; view/edit workflows are auxiliary tools.
(()=>{
 const dialog=document.createElement('dialog');dialog.id='sceneAuxiliaryDialog';dialog.style.cssText='width:1600px;max-width:96vw';dialog.innerHTML='<div class="modal-head"><h2>场景辅助功能</h2><button data-close>关闭</button></div><p class="subtle">其他机位、微调、参考图、生成尺寸、批量放大与工作流都在这里。主页面展示本场景主参考图。</p><div data-body></div>';document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();
 function paint(){
  const scene=currentScene(),panel=document.querySelector('#panel'),editor=panel.querySelector('.scene-editor');if(!scene||!editor)return;
  const cards=[...editor.children],list=cards[0];if(cards.length<3)return;
  const body=dialog.querySelector('[data-body]');body.replaceChildren();
  const head=panel.querySelector('.section-head'),add=panel.querySelector('#sceneAdd');
  const aux=document.createElement('div');aux.className='scene-auxiliary-editor';cards.slice(1).forEach(c=>aux.append(c));
  for(const node of [...panel.children])if(node!==editor&&node!==head)body.append(node);
  if(head)body.append(head);body.append(aux);panel.replaceChildren();
  const header=document.createElement('div');header.className='section-head';header.innerHTML='<div><h3>场景设计</h3><p>按剧情建立场景，以一张空场景主图固定空间与光照。</p></div>';
  const tools=document.createElement('div');tools.style.cssText='display:flex;gap:8px;flex-wrap:wrap';const open=document.createElement('button');open.textContent='辅助功能';open.onclick=()=>dialog.showModal();tools.append(open);if(add)tools.append(add);header.append(tools);panel.append(header);
  const main=document.createElement('div');main.id='sceneMasterMain';main.className='editor scene-master-main';main.append(list);
  const card=document.createElement('section');card.className='card';const version=selectedSceneVersion(scene,'master');
  const heading=document.createElement('div');heading.className='preview-head';const name=document.createElement('b');name.textContent=scene.name+' · 场景主图';heading.append(name);
  const versions=(scene.sceneVersions||[]).filter(v=>(v.view_key||'master')==='master'&&v.image_url),select=document.createElement('select');select.setAttribute('aria-label','场景主图版本');select.style.cssText='width:auto;max-width:55%;margin:0';
  if(!versions.length){const option=document.createElement('option');option.textContent='尚未生成';select.append(option);select.disabled=true;}
  else{versions.forEach((v,i)=>{const option=document.createElement('option');option.value=v.id;option.textContent='V'+(i+1)+' · '+(v.width&&v.height?v.width+' × '+v.height:'主图');select.append(option);});select.value=version.id;select.onchange=()=>{scene.activeVersions??={};scene.activeVersions.master=select.value;scene.confirmedMasterJobId=select.value;save();render();};}heading.append(select);card.append(heading);
  const preview=document.createElement('div');preview.className='scene-master-main-preview';
  if(version?.image_url){const a=document.createElement('a');a.href=version.image_url;a.target='_blank';a.rel='noopener';const img=document.createElement('img');img.src=version.image_url;img.alt=scene.name+' · 空场景主图';a.append(img);preview.append(a);}else{const empty=document.createElement('div');empty.className='empty-stage';empty.innerHTML='<div class="stage-icon">▧</div><p>生成或导入空场景主图</p><small>固定建筑、地标、天气与光线，人物在分镜中加入。</small>';preview.append(empty);}card.append(preview);
  const status=document.createElement('p');status.className='subtle';const job=scene.jobs?.master;status.setAttribute('role','status');status.textContent=sceneBusy(job)?'场景主图生成中…':job?.status==='failed'?'生成失败：'+job.error:version?'当前采用的场景主参考图':'暂无场景主图';card.append(status);
  const actions=document.createElement('div');actions.style.cssText='display:flex;gap:12px;align-items:center;flex-wrap:wrap';const generate=document.createElement('button');generate.id='generateSceneMasterMain';generate.className='primary';generate.textContent=sceneBusy(job)?'场景主图生成中…':version?'重新生成场景主图':'生成场景主图';generate.disabled=Object.values(scene.jobs||{}).some(sceneBusy);generate.onclick=()=>{scene.activeView='master';scene.editIntent='build';save();generateScene(scene);};actions.append(generate);
  const upload=document.createElement('button');upload.textContent='导入场景图片';upload.onclick=()=>{scene.activeView='master';save();render();dialog.showModal();const fold=dialog.querySelector('#sceneUploadFold');if(fold)fold.open=true;dialog.querySelector('[data-external-upload] button')?.click();};actions.append(upload);
  if(version?.image_url){const download=document.createElement('a');download.href=version.image_url;download.download=scene.name+'-场景主图.png';download.textContent='下载图片';download.style.color='var(--green)';actions.append(download);}card.append(actions);main.append(card);
  const settings=document.createElement('section');settings.className='card';const label=document.createElement('label');label.textContent='场景描述';const prompt=document.createElement('textarea');prompt.id='sceneMasterDescription';prompt.setAttribute('aria-label','场景主图描述');prompt.rows=13;prompt.value=scene.prompt||scene.generation?.positive_prompt||'';prompt.oninput=()=>{scene.prompt=prompt.value;scene.generation??={};scene.generation.positive_prompt=prompt.value;save();};label.append(prompt);settings.append(label);const note=document.createElement('p');note.className='subtle';note.textContent='描述环境、建筑结构、固定地标、天气和光源。不同机位复用这张主图，在辅助功能中生成。';settings.append(note);main.append(settings);panel.append(main);
 }
 const before=renderScenes;renderScenes=function(){dialog.querySelector('[data-body]').replaceChildren();before();paint();};
 const style=document.createElement('style');style.textContent='.scene-master-main{grid-template-columns:160px minmax(360px,1fr) 320px;align-items:start}.scene-master-main-preview{margin:16px 0;background:#080d14;min-height:240px;border-radius:8px;overflow:hidden;display:grid;place-items:center}.scene-master-main-preview a{width:100%;display:block}.scene-master-main-preview img{width:100%;height:auto;max-height:540px;object-fit:contain;display:block}.scene-auxiliary-editor{display:grid;grid-template-columns:minmax(350px,1fr) 340px;gap:18px;align-items:start}.scene-auxiliary-editor>.card{min-width:0}.scene-master-main .scene-fold{display:none}#sceneMasterDescription{font-size:12px}@media(max-width:1300px){.scene-master-main{grid-template-columns:140px minmax(0,1fr)}.scene-master-main>.card:last-child{grid-column:1/-1}}@media(max-width:720px){.scene-master-main,.scene-auxiliary-editor{grid-template-columns:minmax(0,1fr)}}';document.head.append(style);render();
})();
